package com.bitedash.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="reviews",uniqueConstraints=@UniqueConstraint(columnNames={"user_id","restaurant_id"})) public class Review { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id") private User user; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="restaurant_id") private Restaurant restaurant; @Column(nullable=false) private int rating; private String comment; @Column(name="created_at") private LocalDateTime createdAt=LocalDateTime.now(); protected Review(){} public Review(User u,Restaurant r,int rating,String comment){user=u;restaurant=r;this.rating=rating;this.comment=comment;} public Long getId(){return id;} public User getUser(){return user;} public Restaurant getRestaurant(){return restaurant;} public int getRating(){return rating;} public String getComment(){return comment;} public LocalDateTime getCreatedAt(){return createdAt;} }
